import math

def calculate_E(a, b, c, N=1001):
    # E = sqrt(N/a) + sqrt(N/b) + sqrt(N/c)
    try:
        term_a = math.sqrt(N / a)
        term_b = math.sqrt(N / b)
        term_c = math.sqrt(N / c)
        E = term_a + term_b + term_c
        # Check if E is close to an integer
        return round(E), abs(E - round(E))
    except ValueError:
        # Should not happen as a, b, c are positive
        return None, None

# Divisors of 1001 (7 * 11 * 13)
divisors = [1, 7, 11, 13, 77, 91, 143, 1001]
solutions = []

# Check all triples where a, b, c are divisors of 1001
print("Checking triples (a, b, c) where a, b, c are divisors of 1001...")
for a in divisors:
    for b in divisors:
        for c in divisors:
            rounded_E, difference = calculate_E(a, b, c)
            if difference < 1e-9:
                solutions.append((a, b, c))

print(f"Number of solutions found among divisor triples: {len(solutions)}")
print(f"Example solution: {solutions[0]}")
